mapper.delete:
delete from product_inquiry
	where pinquiry_id=#{pinquiry_id}
	and user_id=#{user_id}

mapper.update:
update review 
set review_title=#{review_title},
	review_content=#{review_content}
where review_id=#{review_id};

mapper.select:
select u.user_id,u.user_name,u.user_nickname
from user_detail u
where user_id=#{user_id};

SELECT pinquiry_id
FROM product_inquiry
WHERE USER_ID = #{userId}
AND PRODUCT_ID = #{targetId}
ORDER BY pinquiry_date DESC
LIMIT 1
